    summary: "鳌拜（？—1669），瓜尔佳氏，满洲镶黄旗人，清初权臣。他历事皇太极、顺治两朝，皮岛、松锦、入关诸役屡立战功，赐号巴图鲁，号称满洲第一勇士。顺治十八年受遗命与索尼、苏克萨哈、遏必隆辅佐幼帝玄烨。索尼病故后，鳌拜独揽大权，圈换旗地、诛杀重臣、压制言路，皇权旁落。康熙八年五月，康熙帝以布库少年将其当殿擒获，列三十大罪，念其前功免死禁锢，鳌拜不久卒于禁所。康熙五十二年，朝廷追念其战功，赐一等阿思哈尼哈番，子孙世袭。此案是康熙亲政、皇权集中的关键一步。",
    background: "顺治十八年（1661）正月，世祖福临驾崩，年方八岁的皇三子玄烨继位，是为康熙帝。主少国疑，世祖遗命内大臣索尼、苏克萨哈、遏必隆、鳌拜四人为辅政大臣，代行国政，凡政令皆由四辅臣署名颁行。四人皆出自上三旗：索尼隶正黄旗，苏克萨哈隶正白旗，遏必隆与鳌拜同隶镶黄旗。入关未久，黄白两旗旧怨未消——当年多尔衮摄政时，曾把本属镶黄旗的庄屯拨归正白旗，两旗因此积仇数十年。鳌拜以战功起家，性情刚愎，四人中资历虽浅而气焰最盛；索尼年老多病，遏必隆怯懦附和，苏克萨哈势单力薄。权力失去制衡，辅政体制遂由共同理事渐变为一人的专断。八旗制度之下，旗权与皇权本就纠缠不清，少帝年幼，正是权臣窃弄威福的空隙。四辅臣又代表入关初满洲勋贵的共同利益，他们废内阁、复内三院，率祖制以自重，使辅臣之所行往往凌驾于皇权之上。",
