    interpretation: "鳌拜案的深层逻辑，须置于清初政治制度转型中观察。八旗制度下，旗主、议政王与皇帝本有权力重叠，入关后皇权欲集中，而满洲勋贵以战功和旗权为凭，形成集体性的「贵族辅政」传统。顺治遗诏设四辅臣，本是幼帝在位时的权力代偿机制，但它取消了内阁票拟、六部执行、科道封驳之间的衔接，辅臣直揽政柄，制衡全凭个人资望。鳌拜并非雄才大略之篡臣，其专权是制度失衡的产物：索尼老病、遏必隆怯懦、苏克萨哈孤立，四人共理遂变一人独断。康熙帝以布库少年当殿擒之，刻意将一场政治清洗化作家奴擒主的「宫中嬉戏」，既避免两黄旗武力反弹，又收不世之奇功，其政治手腕之老成远超年龄。三十大罪而免死禁锢，是「功过分治」之策；康熙五十二年追赐男爵、雍正朝复公爵、乾隆朝再降为男，则是帝王以施恩与裁抑驾驭功臣后裔的经典手法。此案标志着满洲贵族辅政旧制终结、皇权独尊格局确立，为随后平定三藩、统一台湾等事业提供了制度前提，也为此后清代权臣政治的讨论留下永久样本。",
