    interpretation: "白莲教起义之爆发，非一朝一夕之故，乃乾隆盛世表象之下结构性矛盾之总爆发。其时人口倍增而土地兼并日烈，川楚陕边区流民无以为生；吏治自和珅用事以来败坏已极，州县官以教案为利薮，株连敲索，驱民从乱，王三槐「官逼民反」一语实为乱源之确切注脚。就军事而言，义军以宗教为纽带，聚散无常，流动作战，正规军进退失据；清廷终赖坚壁清野、寨堡团练困毙之。此策虽收功于一役，却开启兵权下移之渐：乡勇因功得官，地方自募兵勇，隐为后来湘淮军兴、督抚势重之先声。二亿两军费耗尽国帑，清廷财政从此长亏，捐纳、加征相继而行，民生益困。故此役虽平，而清王朝根基已动，由盛转衰之势遂不可逆转。",
