          "慈禧死后葬于普陀峪定东陵，谥曰孝钦慈禧端佑康颐昭豫庄诚寿恭钦献崇熙配天兴圣显皇后，字数之多为清代后妃之最。宣统三年（1911），即她死后三年，辛亥革命爆发，清朝二百六十八年的统治宣告终结。慈禧以一人之身，同洋务、维新、新政三场自救运动相始终：她并非一味守旧，却始终把权力安全置于制度变革之上。她留下的，是一个训练了新军、废除了科举、打开了立宪之门，却依然找不到权力交接与制度转型之路的帝国。"
