    interpretation: "此战起因，表面为「护旗」「护教」之争，实则《南京条约》体系已难满足列强扩张之欲，修约交涉无果之后，武力遂成必然手段。清廷之败，非尽在器物，而在体制与见识：咸丰帝以「天朝」自居，既不愿公使驻京，又不谙敌情，和战之策朝令夕改；叶名琛式的强硬，实为无备之盲勇。大沽一胜反招更大报复，通州擒使更授敌以焚园之口实。战后公使驻京、总理衙门设立，中外关系被迫纳入近代条约体系；沙俄趁火打劫，掠地逾百万平方公里，为近代失地之最。圆明园一炬，既焚毁百年园林之精华，亦烧醒部分士大夫之迷梦，直接催生「师夷长技以自强」的洋务运动。中国半殖民地化程度由此加深，条约体系之枷锁自此愈缠愈紧。",
