    interpretation: "多尔衮是清初政治舞台上最关键、也最具争议的人物。论武功，他抓住崇祯自缢、李自成立足未稳的千载良机，统兵入关，一片石一战定乾坤，使偏处辽东的政权一跃而为统治全中国的王朝；论政治，他在皇太极暴卒、八旗内战一触即发之际，以拥立幼主的折中方案化解萧墙之祸，又以迁都北京、礼葬崇祯、开科取士奠定统治格局，其战略眼光与果断手腕在同时代人物中罕有其匹。然其执政失误同样深重：剃发、圈地、投充、易服诸令，以民族高压手段强行推行的满洲习俗与经济制度，激起江南惨烈抗清，使统一代价倍增；其倾陷豪格、僭越礼仪、独揽大权，更使皇权与摄政权之间积怨深重，终招死后毁墓鞭尸之祸。乾隆四十三年复爵昭雪，实为皇权稳固之后对开国功勋的重新确认，其历史地位自此落定。",
