    interpretation: "福临的一生，是清初权力格局转换的缩影。他的皇位并非父皇钦定，而是满洲贵族相持不下时的折中；少年时代，皇权旁落于摄政王之手。正因如此，亲政之后他急欲收揽权柄：清算多尔衮、平反旧案、整饬吏治、倚用汉臣，桩桩件件都在把国政从旗主会议移归皇帝一人。他尊崇儒学、视学释奠、改定孔子封号、开科取士，是要在满洲武功之外，为清朝在中原另立文治正统；满汉一家之策，则将入关之初的民族鸿沟稍稍填平。在位十八年，制度上改内三院为内阁、复翰林院、严宦官之禁，已具一代王朝规模。他去世虽早，所定路线却被康熙以后诸帝全盘继承；遗诏选立出过天花的玄烨，更直接造就了后来的康熙盛世。清朝能由马上得天下转为马下治天下，转折正完成于这位二十四岁早逝的皇帝手中。",
