    interpretation: "改土归流之深层逻辑，在于中央集权从间接羁縻走向直接郡县的必然推进。元明两朝以土司羁縻西南，本因山川险远、兵力财赋有所不逮；及至清代，西南与内地经济联系日密，人口流动、垦殖商货渐通，土司割据其间的弊病日益凸显：私征、仇杀、阻驿、抗命，既扰民生，亦损国赋与一统之威。雍正帝以大权统于一尊为念，鄂尔泰以「云贵大患，无如苗蛮」为忧，君臣合力，遂以改流为根治之策。其法恩威并施，先计擒而后兵剿，故成本虽巨而收功较快。然改流并非全然平稳：乌蒙之变、苗疆起事、金川之役，皆示急进之代价。乾隆朝调整策略，剿抚并用、慎用兵威、重善后安插，新疆六厅与金川设厅，遂使郡县体系渐次稳固。就长远论，改流奠定了西南边疆省县建置与多民族共处的基本格局，促进了经济一体化与民族交融，是清帝国治理从因俗而治走向一体化的关键一步。",
