    interpretation: "十三行制度的兴废，折射出清代对外政策的深层逻辑。清廷开海设关，本为征收税饷、休养生息，然其着眼始终在「防」而非「通」：迁界禁海是防郑氏，一口通商是防洋人杂处，防范外夷规条是防华洋交接。以行商居间，官府不与外商直接往来，是将贸易纳入王朝管控的秩序之中，而非视为平等的邦交。这套制度在近百年间维系了广州的独占繁荣，粤海关税饷充盈，行商富甲天下，但其代价是中外之间的隔膜日益加深：外商困于商馆，不能自由贸易，不能久居，不能学习华语，怨怼日积，终以鸦片战争的方式爆发。十三行焚毁之后，沙面租界与各口洋行代之而起，朝贡体系下的旧式外贸管理体制，终于让位于条约体系下的新秩序；而十三行时期培育的行商后人与商业网络，又在此后的买办制度与沿海贸易中留下绵长的余响。",
