          "乾隆五十八年（1793 年），英王乔治三世遣马戛尔尼使团来华，请开宁波、舟山等处通商口岸、租借海岛并派使臣驻京。弘历以「天朝物产丰盈，无所不有，原不藉外夷货物以通有无」拒之，仅许广州一口通商，使团无功而返。此时英国已处于工业革命之中，而清廷上下仍视之为朝贡体系中的一员。嘉庆元年（1796 年）正月，白莲教起于楚豫陕川，清廷调动十八省兵力，耗银逾一亿两，战事绵延九年，八旗、绿营战斗力之孱弱暴露无遗。",
          "乾隆六十年（1795 年）九月，弘历宣布立皇十五子颙琰为皇太子，明年正月初一禅位，改元嘉庆，自称太上皇帝，仍御训政。他自言在位六十年，不敢超过祖父康熙六十一年之数，以示孝道。嘉庆四年（1799 年）正月初三，弘历崩于养心殿，年八十九岁，庙号高宗，葬裕陵。太上皇崩后不过半月，嘉庆帝即下和珅于狱，赐自尽，籍没家产，民间相传值银八亿两之巨，遂有「和珅跌倒，嘉庆吃饱」之谣。盛世余晖，至此散尽。"
