    interpretation: "弘历一生，恰是传统帝制盛衰的完整标本。他把清代武功推向极盛：新疆入版、金川归流，疆域达一千三百万平方公里以上，多民族国家的版图由此奠定，这是他留下的最大政治遗产。但他的统治术也把君主专制推向极致：文字狱与《四库全书》互为表里，奖惩皆出宸衷；和珅专权二十余年，正是皇权绕过制度、私相授受的结果。所谓盛世，此时已靠人口膨胀与白银流入勉强支撑，治理技术却无实质进步；一口通商与朝贡体系，又使中国错过与世界同步的窗口。史家论清，谓康熙创基、雍正积业、乾隆挥霍，虽非尽然，亦得大体。弘历以一身兼盛世之缔造者与终结者，此中悖论，正是理解清代由盛转衰的关键。",
