    interpretation: "皇太极是清朝由部落军政联盟向中央集权帝国转型的关键人物。他继位时，后金仍是「八王共治」的军事贵族政体；他离世时，已是一个设有六部三院、满蒙汉八旗、藩属朝鲜与蒙古的封建帝国。其功绩不仅在于武功，更在于制度：文馆译书、六部行政、科举取士，皆是对中原王朝治理体系的系统性移植；改族名满洲、定国号大清，则完成了从「后金」这一区域性政权向「天下王朝」的身份重构。五次绕道入关虽未据一城，却持续消耗明朝国力、动摇其统治根基；松锦之战歼灭明军最后主力，使入关从「不能」变为「可能」。可以说，没有皇太极的十七年经营，便没有多尔衮1644年的入关定鼎。其猝逝留下的权力真空，险些重演太祖身后的纷争，幸有孝庄太后与济尔哈朗折中，方有顺治之立。",
