    interpretation: "军机处之立，其表为军事之亟，其里为君权之专。雍正帝以一人之明察，将谕旨撰拟、机密寄发、大政参议之权，悉收于禁中一室，使内阁徒存其名，议政王大臣会议并归裁撤，督抚奏折直达御前，廷寄上谕径下封疆，上下之间再无隔阂，亦再无牵制。自此皇权无所分、无所碍，中国古代君主专制由是达于顶峰。然利之所在，弊亦随之：军机大臣无衙署属官，权不固定，不过承旨办事，一旦失宠，如和珅之煊赫，一夕而覆。此制使国之大政系于一人之身，帝明则政举，帝昧则事败，和珅专擅、慈禧操柄，皆其流弊也。论者谓军机处集历代君权之大成，亦伏晚清大变局之机括，诚非虚语。",
