    summary: "康有为（1858—1927），原名祖诒，字广厦，号长素，广东南海人，故称「康南海」。光绪二十一年（1895）进士，授工部主事。他是晚清维新运动的领袖，先后撰《新学伪经考》《孔子改制考》，以「托古改制」之说为变法奠定理论基础；同年联合十八省举人一千三百余人公车上书，请拒和、迁都、变法。光绪二十四年（1898）受光绪帝召见，参与主持戊戌变法，为变法主将；政变后流亡海外，在加拿大组织保皇会，坚持君主立宪。晚年反对共和，1917年参与张勋复辟，拥溥仪复位，十二日即败；1927年病逝于青岛，享年七十岁。其一生由维新先驱而终为保皇遗老，是中国近代史上影响深远而又争议极大的人物。",
    background: "康有为所处的时代，正值清王朝内忧外患交织。道光以后，列强环伺，鸦片战争、英法联军之役接踵而至；甲午一役，北洋水师全军覆没，光绪二十一年（1895）《马关条约》签订，割台湾、赔款二万万两白银，国势危如累卵。与此同时，西学东渐，早期维新思想已启端绪，冯桂芬著《校邠庐抗议》，王韬办报立论变法，郑观应撰《盛世危言》，皆主张采西学、制洋器、设议院。康有为生于广东南海县苏村，早年受学于同县名儒朱次琦，博通经史，又好公羊家言，从今文经学中发掘「通三统、张三世」之义，主张托古改制。光绪十四年（1888），他第一次上书光绪帝，提出「变成法、通下情、慎左右」三项主张，书虽未达天听，其忧国之心已昭然可见。甲午战败后，民族危机骤深，维新思潮涌动，为他登上政治舞台提供了历史契机。",
