          "辛亥革命后，清室倾覆，康有为仍坚持其保皇立场，反对共和。民国元年（1912），他在上海组织孔教会，自任会长，倡导尊孔读经、以孔教为国教，欲以旧道德维系世道人心。1917年6月，张勋统兵入京，拥废帝溥仪复辟，康有为亦参与其事，被授为弼德院副院长。然复辟仅十二日，即被段祺瑞讨平，康有为遭通缉，先避入美国使馆，后辗转遁走，此役使其晚年声名再受重创。",
