    interpretation: "康有为以今文经学为变法张本，其「托古改制」之论借孔子之名行维新之实，既降低了激进变革在士林中的阻力，也把改革理论系于经学权威之上，一旦失败，便被守旧派以「非圣无法」之名反噬。公车上书打破士子干政之禁，开启近代知识分子集会请愿之先声；戊戌维新之失败，根因在于帝党无实权、维新派无军队无群众基础，慈禧集团一反扑即成摧枯拉朽之势。流亡以后，保皇立宪由进步立场渐成保守之帜，与革命时代相逆，1917年参与张勋复辟更使其晚年形象受损。然其在思想启蒙、教育、孔教运动中的复杂角色，使其成为传统士大夫向近代知识分子转型的典型人物。梁启超誉其为「先时之人物」，而章太炎讥其执迷保皇，褒贬之间，正见其历史地位之复杂多面。",
