    summary: "旻宁（1782—1850），原名绵宁，清宣宗，嘉庆帝次子，清军入关后第六位皇帝，亦为清朝唯一以嫡长子身份继位的皇帝。1820年至1850年在位，年号道光。在位三十年躬行节俭，裁减宫廷用度，平定张格尔之乱；1838年任命林则徐赴广东禁烟，次年虎门销烟震动中外。鸦片战争中清军节节败退，1842年被迫签订《南京条约》，割地赔款、五口通商，中国由此步入近代。1850年病逝，终年六十九岁，葬慕陵。",
    background: "乾隆末年，清朝已现由盛转衰之兆：和珅擅权二十余年，吏治大坏，国库虚耗。嘉庆一朝勉力支撑，川楚白莲教起事九年，耗银逾万万两，元气大伤；嘉庆十八年天理教徒攻入紫禁城，更令朝廷颜面尽失。至旻宁继位时，国势已如烈日西沉，漕运、盐政、河工三大政弊病缠身，户部存银不及乾隆盛世之半。与此同时，世界格局正天翻地覆：英国已完成工业革命，棉纺织业产能激增，急需打开中国这个庞大而封闭的市场；东印度公司在印度的鸦片种植业日见成熟，鸦片成为英国平衡对华贸易逆差的利器。道光初年，鸦片输入量自每年数千箱激增至数万箱，白银滚滚外流，银钱比价由嘉庆年间一两白银兑钱一千文上下，涨至道光十八年前后的兑一千六七百文。民生日困，国用日蹙，一场中西之间前所未有的碰撞，已在海平线上酝酿。",
