    interpretation: "旻宁之世，清朝已入「衰世」。其人非昏暴之君：论勤政、论节俭，在清代帝王中堪称表率；然其失不在德，而在识与势。当英国以工业革命之利器叩关而来，农业中国与之相抗，胜负早已注定：军备之代差、财政之困竭、吏治之积弊、信息之蔽塞，皆非一人之恭俭所能弥补。旻宁于禁烟之初本有定力，英舰北上之后却游移剿抚、和战无恒，终以一纸《南京条约》了局，割地赔款、五口通商，开中国近代不平等条约体系之端。百余年来，论者多视其为「守成而未成」之君：守祖宗之业而业已倾圮，知节俭而不知变革。他身后的中国，被迫卷入全新的世界秩序，而他本人则成为古典时代最后的守门人之一。",
