    interpretation: "努尔哈赤一生，自二十五岁遗甲起兵至六十八岁殒身叆鸡堡，凡四十四年，恰与明朝由衰而乱之岁月相始终。其成功非止于勇武：一则明廷自万历怠政，辽东空虚，李成梁以夷制夷之策反为所乘，此为时势；二则八旗制度以牛录为根、寓兵于民，使散处山林之渔猎部众在数十年间凝聚为组织严密之军事集团，此为制度；三则满文创制，使政令自通、文化认同渐成，此为满族共同体形成之枢。而宁远一败，又昭示火器时代攻防之变——红夷大炮据城而守，骑兵野战之长难施，此后皇太极、康熙皆重火器，明清之争转入新局。努尔哈赤未及见清军入关，然其并女真、立八旗、创满文、都沈阳，已为清朝天下凿下根基。",
