          "《明史》载吴三桂行至途中，「闻爱姬陈圆圆为自成将刘宗敏掠去，怒，仍还山海关」。陈圆圆本为名妓，后入国丈田弘遇府为歌姬，吴三桂纳之，留于京宅。吴三桂深恨大顺辱其家室，遂于三月下旬回师山海关，一举击溃唐通所部，重夺关城，传檄远近，誓与大顺为敌。唐通残部狼狈西逃，李自成闻变，决意亲征。吴三桂自知四万孤军不足抵挡大顺主力，乃遣使驰赴关外，向清朝摄政王多尔衮乞师请援，愿以重宝犒军，共破大顺。"
