          "施氏后人亦继其海防之业。其子施世骠官至福建水师提督，康熙六十年（1721）率兵平朱一贵之乱，保全台湾；另一子施世纶历任泰州知州、漕运总督，以清廉著称，民间「施公」之讼案，后衍为戏曲小说。施琅本人则于雍正十年入祀贤良祠，乾隆时国史馆修《贰臣传》未将其列入，盖以其功业赫然，非朝秦暮楚者可比。",
