    interpretation: "施琅的历史地位，须置于两条脉络中理解。其一为明清鼎革的尾声：郑氏以海上力量抗清数十年，清廷迁界禁海，耗银数千万，终赖施琅一战而定，东南海疆始得晏然；其二为台湾建制的开端：澎湖战后，朝议主弃者众，施琅独排众议，上《恭陈台湾弃留疏》，以「四省藩篱、八闽门户」立论，使清廷决意设府置县。台湾自康熙二十三年（1684）隶于福建，至光绪十一年（1885）建省，二百年间治理格局，实奠基于此。施琅以杀父之仇而能不修旧怨、亲祭郑成功之庙，以贰臣之身而能成不世之功，其一身系海疆安危者近四十年，此所以超出寻常功臣，而为奠定台湾建制之关键人物。",
