    summary: "「十全武功」是清高宗乾隆帝在位期间自诩的十次重大军事胜利：两平准噶尔、一定回部、两扫金川、一靖台湾、降缅甸、降安南、两降廓尔喀。自乾隆十四年（1749）第一次金川之役起，至五十七年（1792）廓尔喀乞降止，绵延四十余年，战火遍及天山南北、川西高原、西南边徼与台湾海峡。五十七年，乾隆帝撰《十全记》，勒石避暑山庄，自号「十全老人」。十次用兵将清朝版图推至极盛，新疆、西藏由此牢固归入版图，统一多民族国家之疆域格局基本奠定；然军费浩繁，耗银逾万万两，国势由盛转衰，实为清朝中衰之伏笔。",
    background: "清初至乾隆初，西北准噶尔部雄踞天山南北，据伊犁为庭，控弦数十万，屡与清朝争锋，前后七十余年。康熙帝三征噶尔丹（乌兰布通、昭莫多之捷），雍正朝傅尔丹和通泊之败、丧师万余，皆未竟全功；至雍正十一年（1733），清与准噶尔始议定以阿尔泰山为界，暂息干戈。乾隆十年（1745），准噶尔台吉噶尔丹策零死，诸子争立，达瓦齐、阿睦尔撒纳相攻，部内大乱。乾隆帝承祖父积累之国力，府库充盈，户口滋长，决意一举解决西北边患。西南大小金川土司、缅甸雍籍牙王朝、安南西山朝及廓尔喀（今尼泊尔）或内叛、或扰边、或犯属国，战火遂遍及西北、西南与海疆。此时户部库银常存三四千万两，八旗、绿营兵额逾八十万。乾隆帝以「大一统」自期，恃满洲铁骑、绿营与雄厚财力，十次用兵，晚年汇为「十全武功」。其战略不仅在于安边，更在将蒙古、回部、西藏纳入直接治理，完成康雍两朝未竟之业。",
