    interpretation: "「十全武功」之名，出乾隆帝自撰《十全记》，自述十役次第。考其实，两平准噶尔、一定回部，扫清准部割据，天山南北正式归入版图；两定廓尔喀后，立《钦定藏内善后章程二十九条》，以金瓶掣签定呼毕勒罕之承嗣，西藏归于驻藏大臣节制，此皆清代边疆治理之根本变革，惠及后世。然十功之实，未必皆「全」：安南之役，孙士毅丧师于栋多，提督许世亨阵亡，实为败局，赖阮光平乞和受封，始转败为「功」；初次金川、初次廓尔喀，亦多为和局而非歼敌。乾隆以「十全」自诩，正见其晚年粉饰太平、好大喜功之一面。十役军费，据《清史稿·食货志》所载，二次金川六千三百余万两，准部三千三百余万两，廓尔喀一千一百万两有奇，合计逾万万两。国库由充盈渐就虚耗，八旗以久役疲惫，嘉庆元年（1796）白莲教事起，清朝遂由盛转衰，论者因以「十全武功」为清朝中衰之伏笔。",
