    interpretation: "《四库全书》的双重性，根源在于乾隆帝「寓禁于征」的纂修策略。征书令一下，天下典籍聚于朝廷，朝廷得以逐书查核：合意者收入四库，违碍者禁毁删改。故此书既是古代图书的总结，也是皇权对学术思想的整肃。从积极一面看，三百六十余位一流学者历时十年，校定三千四百六十一种古籍、辑出《永乐大典》佚书三百八十五种，并以《总目提要》建立学术统序，乾嘉考据学由此勃兴，后世《四库全书存目丛书》《续修四库全书》之编纂亦以其为根柢。从消极一面看，三千一百余种书籍被毁，王锡侯《字贯》案、徐述夔《一柱楼诗》案株连广泛，士人因畏惧而远离当世之学，思想活力长期受挫。七阁分藏制度使全书在战乱中得以部分存世，文渊、文溯、文津、文澜四本至今俱在，而文源、文宗、文汇三本连同数万册典籍同付劫灰，恰是这一文化工程命运多舛的缩影。功罪交织，才是《四库全书》的完整历史定位。",
