    summary: "孙中山（1866—1925），名文，字逸仙，化名中山樵，广东香山人，中国民主革命的先驱。1894年在檀香山创立兴中会，1905年在东京合并各派组成中国同盟会，被推为总理，倡「驱除鞑虏，恢复中华，创立民国，平均地权」，并凝练为民族、民权、民生的三民主义。自1895至1911年，他先后发动十次武装起义，屡败屡战。1911年武昌首义、各省响应，1912年1月1日，他在南京就任中华民国临时大总统，宣告帝制终结。此后历经讨袁、护法之役与陈炯明叛变，晚年改组国民党，确立联俄、联共、扶助农工三大政策，创办黄埔军校。1925年3月12日病逝于北京。",
