    interpretation: "太平天国运动是中国旧式农民战争的最高峰，也是晚清变局的总枢纽。它以宗教聚众、以平均号召，却始终未能真正解决农民土地问题，《天朝田亩制度》的美好愿景止于天京城内；《资政新篇》虽开近代化先声，却无施行条件，空留纸上蓝图。其兴也勃，其亡也忽：宗教狂热可以聚众，却无法替代制度建设；权力集中于杨秀清一人，终于酿成天京事变的自相残杀，由盛转衰。对清廷而言，经制之兵八旗、绿营朽钝不堪，镇压之责落入湘淮汉人之手，兵权、财权下移，督抚权重，中央集权根基动摇；战后厘金、督抚专权、洋务自强接踵而至，满汉格局与权力结构为之一变。同时，战火波及十八省，江南膏腴之地化为焦土，人口损失以千万计，学界至今未有定论；列强又借「助剿」攫取长江权益。太平天国既是大清王朝的催命符，也是近代中国变革的起点之一。",
