      {
        heading: "余波：士林风气之摧折",
        paragraphs: [
          "三朝文字狱，其刑有戮尸、弃市、凌迟、灭族，其罚有籍没、流放、发遣为奴。亲属门生株连殆尽，远戍东北之沈阳、宁古塔、卜魁，与新疆之乌鲁木齐、伊犁。士人因一字一句之嫌，即破家灭门。雍正十年吕留良一案，自石门一县，牵连浙省士子数十家；乾隆四十二年王锡侯一案，江西巡抚以下府县官降罚有差。告讦之风由此大盛，仇家挟嫌、无赖图赏，皆得以笔墨兴狱，一人告讦，百家破灭，此清代文字狱株连之尤酷者也。",
          "士林噤若寒蝉，不敢妄谈国是，思想活力为之斫丧。士人乃遁入训诂考据，乾嘉朴学遂盛，惠栋、戴震、钱大昕、王念孙辈，埋首经史，不问时事。其弊在于谨愿者株守书卷，豪杰者钳口避祸，著书为稻粱谋而已。晚清龚自珍咏之曰：「避席畏闻文字狱，著书都为稻粱谋。」盖实录也。宋明以来士大夫清议干政之风，至此斩然，此非独学术之转向，实士气之摧折。",
          "其流风余烈，百余年间犹令读书人谈虎色变。典籍亡佚无算，史乘残缺，思想禁锢已成积习。清仁宗嘉庆亲政，文网渐弛，告讦之风始杀，然士习已成畏葸，求新知、论时政者寥寥。论者谓清代学术所以偏于故纸而不及西学之新，文字狱之禁锢，实为一因。三朝君主借此钳制言论、摧折士气，禁毁典籍无算，实为中国文化史上一大劫厄。"
        ]
      }
