    interpretation: "清代文字狱非寻常刑狱，其要害在以思想定罪、以文字成狱。满洲以少数民族入主中原，华夷之防最触忌讳，君主既要铲除反清思明之念，压制汉族士人民族意识，又要驯服士林于皇权之下。康熙宽严并施，以博学鸿词羁縻遗民，而庄、戴两案不稍宽假；雍正恩威兼用，自作《大义觉迷录》与臣民辩论，又以吕留良之戮尸立威；乾隆则借修《四库全书》之际，把一案一狱化为遍行之制度，禁毁典籍无算。其深远影响：典籍亡佚、史乘残缺；士人转向考据，避谈政治，乾嘉汉学之盛与经世之学之衰同一源流。士气斫丧、思想僵化，百余年后读书人犹谈虎色变，实为中国文化史上一大劫厄，亦为近代落后之伏因。",
