    interpretation: "戊戌变法之败，后人论说纷纭。就权力结构而言，光绪帝虽居九五，而无军权、无财柄、无亲信之臣：翁同龢开缺在变法前两日，军机四卿不过章京之职，维新派所依者唯康梁等布衣书生与袁世凯一支新军。新政百日之间诏令一百余道，督抚观望不前，变法之令多悬为空文。废八股、裁冗署同时并举，尽失士子与京官之援，反逼成守旧势力合流；谭嗣同夜说袁世凯围园勤王，更是以国运押于军阀之一掷。至于袁世凯告密与政变先后、康有为所传「衣带诏」之真伪，学界长期考辨，主流认为告密在训政之后，于六君子之诛有推波助澜之责，而非政变之主因。就长远观之，变法虽败，而学堂、报刊、新学之名由此确立，民权、立宪之说自此深入人心；士人由求变法而趋革命，清廷亦于庚子之后踵行新政。六君子以血肉殉维新之业，其精神感召远逾当时之成败，故论者谓戊戌变法为中国近代自上而下改革之尝试，亦为思想启蒙之重要转折。",
