    summary: "1911年10月10日，湖北新军工程第八营在武昌打响起义枪声，一夜之间攻占湖广总督署，建立湖北军政府。两个月内，湖南、陕西、云南、上海等十余省相继独立，清王朝统治土崩瓦解。1912年1月1日，孙中山在南京就任中华民国临时大总统；2月12日，宣统帝溥仪颁诏退位。因爆发于农历辛亥年，史称辛亥革命。这场由同盟会等革命团体长期酝酿的巨变，结束了延续两千余年的君主专制制度，建立了亚洲第一个共和国，却也将未竟的课题留给了此后数代中国人。",
    background: "甲午战败与庚子之变后，清廷承担《马关条约》《辛丑条约》巨额赔款，本息合计逾六亿两白银，各省摊派繁重，社会矛盾激化。1901年起推行新政，废科举、练新军、设咨议局，本欲自救，却因财政枯竭与吏治腐败收效有限。1908年，光绪帝与慈禧太后相继去世，幼帝溥仪即位，醇亲王载沣监国。1911年5月，清廷成立第一届责任内阁，十三名阁员中满族占九人、皇族占七人，被讥为「皇族内阁」，立宪派大失所望。同月，清廷宣布铁路干线国有政策，强行收回商办铁路，激起湘、鄂、川、粤保路运动，四川尤为激烈，同志军围困成都。自1894年兴中会在檀香山成立以来，孙中山、黄兴等以三民主义相号召，1905年在东京成立同盟会，接连发动萍浏醴、镇南关、广州黄花岗等起义。湖北新军万余人中，参加文学社、共进会及倾向革命的士兵逾三分之一，武昌已成一触即发之势。",
