    interpretation: "辛亥革命之成功，不在兵力雄厚，而在旧制度已失信于天下。新政本为自救，却加速瓦解了自身根基：废科举断了士人的利禄之途，练新军把武器与思想一并交给了士兵，设咨议局开启了集会结社的风气，皇族内阁又最后否定了立宪的诚意。革命党人以小搏大，武昌首义不过数千新军，却能牵动天下，正因各省谘议局、新军、商会各自为变，势成连锁。然而帝制虽去，秩序未立：临时政府财政窘迫、号令难行，南北妥协之下大权落入袁世凯之手，此后洪宪帝制、张勋复辟、军阀割据相继而起，可见推翻一姓朝廷易，建成现代国家难。这场革命确立了「敢有帝制自为者，天下共击之」的共识，也将主权在民的观念植入人心，但民主与统一的课题，仍留待后人继续解答。",
