    summary: "清圣祖爱新觉罗·玄烨，顺治帝第三子，顺治十八年（1661）正月八岁即位，次年改元康熙，在位六十一年，是中国历史上在位最久的皇帝。他亲政后擒权臣鳌拜，平定吴三桂等三藩之乱，收降台湾郑氏并设府治理，抗击沙俄、签订《尼布楚条约》，三征噶尔丹，奠定清朝版图；又诏举博学鸿词，敕编《康熙字典》《古今图书集成》，宣布滋生人丁永不加赋，开启康乾盛世，庙号圣祖。其一生武功与文治并重，内平割据、外御强邻、怀柔汉士、轻徭薄赋，使入关未久的清朝扎下根基，《清史稿》论曰「虽曰守成，实同开创焉」。",
