          "西北亦未安。漠西准噶尔部首领噶尔丹崛起，兼并四卫拉特，破叶尔羌，势张一时，虎视喀尔喀蒙古。康熙二十七年（1688），噶尔丹率三万骑兵越杭爱山，大破喀尔喀三部，土谢图汗、车臣汗、札萨克图汗率众数十万南奔内附，玄烨命发仓粮赈济，暂安插于科尔沁牧地。康熙二十九年（1690）六月，帝亲征，以疾还京，命裕亲王福全为抚远大将军、恭亲王常宁为安北大将军，分道迎击；八月，清军与噶尔丹激战于乌兰布通。噶尔丹以万计骆驼缚足卧地，背负箱笼，蒙以湿氊，环列如栅，号为「驼城」，清军以火器前后夹击，大破其阵，噶尔丹仅率数千骑遁走。",
