        paragraphs: [
          "武功既盛，文治并兴。康熙十七年（1678）正月，诏举博学鸿词，中外荐举者一百四十三人；次年三月，帝亲试于体仁阁，取一等二十人、二等三十人，彭孙遹名列第一，俱授翰林，即命入馆纂修《明史》。此举开怀柔汉族士大夫之阶，山林遗民多出应诏，满汉隔阂渐消。康熙二十三年九月，首度南巡，视察黄河、运河，躬亲询问河工利弊，起靳辅为河道总督，修筑堤坝、疏浚下河，黄河数年未为大患。南巡回銮道经曲阜，诣孔庙孔林，行三跪九叩之礼，天下闻风悦服。",
          "敕编之书，蔚为大观。帝命曹寅于扬州设诗局，刊刻《全唐诗》，录诗四万八千九百余首，作者二千二百余人，为唐诗总集之冠；康熙五十五年（1716），《康熙字典》成书，由大学士张玉书、陈廷敬任总阅官，收字四万七千余，分四十二卷，后世字书奉为宗；《古今图书集成》一万卷，由陈梦雷编纂，为类书之大观。此外《佩文韵府》《渊鉴类函》《数理精蕴》次第告成。康熙九年又颁《圣谕十六条》，劝农讲约，教化遍于乡里，文教覃敷，士子蒸蒸。",
          "民生所系，莫如赋役。康熙五十一年（1712）二月，帝颁上谕，以康熙五十年全国人丁二千四百六十余万、征丁银三百二十余万两为定额，嗣后「滋生人丁，永不加赋」，新增人丁不再加征丁银。此举减轻田亩之外负担，人口随之大增，为雍正朝摊丁入亩之先声，亦为康乾盛世之根基。康熙六十一年（1722）十一月十三日，玄烨崩于畅春园，享年六十九岁，遗诏传位于皇四子胤禛，葬景陵，庙号圣祖，谥仁皇帝。在位六十一年间，削平群雄、奠定版图，史称「虽曰守成，实同开创」。"
        ]
