          "康熙十二年（1673）三藩乱起，朝廷调兵南征，无暇北顾，沙俄乘机加固雅克萨、尼布楚据点，边患日深。迨康熙二十年（1681）平三藩、二十二年（1683）统一台湾，康熙帝始得专力东北，视驱逐沙俄、安辑边境为当务之急。康熙二十一年（1682），帝东巡盛京、吉林，泛舟松花江，阅兵习武，安抚诸部；随遣郎坦、副都统朋春等以捕鹿为名，顺黑龙江而下，直抵雅克萨侦察。郎坦归报其城防、兵力、粮储虚实，言罗刹兵寡而城坚，攻取非难，所难者在粮饷转输千里不继。帝深然之，遂以戍守与粮运为根本。",
