    interpretation: "洋务运动之败，非尽在器物，而在制度与人心。其倡导者以「中学为体，西学为用」为圭臬，只取西人器物之末，不问其政教法度之本；官办、官督商办之制，使企业成为衙门附庸，经营仰官意而非市场。运动之权半操于地方督抚，中枢孱弱，财力支绌，各省各自为政，连南北洋海军经费亦互相侵挪；甲午前数年，户部停购船炮，海军经费挪拨园工，已伏败亡之机。再深一层，清廷亲贵与守旧文官集团对洋务疑忌重重，倭仁之流以「礼义为干橹」相难，慈禧太后复以平衡之术操弄其间，使自强始终未能凝聚为国策。故甲午一败，实为三十年制度因循之总清算：以旧制度行新工业，终不可久。然三十年间厂矿、学堂、铁路、电报次第兴办，新式人才辈出，中国社会结构已悄然改变，近代化进程一旦开启，便再无从逆转。",
