          "四月十八日，多铎所率清军主力进抵扬州城下，扎营城西北。其时扬州守军单薄，总兵刘肇基率部自北来援，李栖凤、高凤岐等将领则以兵势不敌，主张献城投降。史可法断然不从，李栖凤等率所部出城降清，城中兵力益发单薄。史可法传檄各镇请兵救援，檄文数下，竟无一至者：黄得功、刘泽清各拥重兵，坐观成败；刘良佐早已暗通清军。多铎自十八日至二十四日，先后五次致书招降，遣降将李遇春等入城游说，史可法皆不启封，誓与扬州共存亡。城中军民数万，在史可法督率下昼夜登城，奋力防守。",
          "史可法深知事不可为，预先安排后事：致书家人，托付嗣子史德威，并留遗书以城亡与亡自誓；又上疏弘光帝，陈报军情，语极悲切。多铎见招降无效，下令攻城。清军以红衣大炮连续轰击，城墙屡塌屡补。四月二十五日，扬州西北城垣被炮火轰开缺口，清军蜂拥登城。总兵刘肇基率残部与清军展开巷战，短兵相接，力竭而死，所部全军覆没。城破之际，史可法拔剑自刎，未殊，一参将拥可法出小东门，遂被执。可法大呼曰：「我史督师也！」遂杀之。其副将、幕僚等从死甚众。",
          "史可法殉国后，正值酷暑，遗体不知所终。据《明史》所载，其嗣子史德威于乱军中遍寻遗骸不得，乃收其衣冠，葬于扬州城外梅花岭上，即后世所称衣冠冢。多铎既杀史可法，以扬州军民拒守抵抗，下令屠城，意在惩创拒抗者、立军威于江南。梅花岭衣冠冢，此后成为故明遗民与士人凭吊忠魂之所。清统一天下后，乾隆四十一年（1776），高宗追谥史可法「忠正」，以褒其忠节——此是后话，但史可法与扬州同殉的悲壮形象，早已深入民间。"
