    interpretation: "扬州十日因何发生？从军事层面看，多铎屠城是一种有意的威慑策略：扬州为清军南下江南的门户，抵抗最力，杀一儆百，可瓦解南明各州县的抵抗意志。从政治层面看，多尔衮在占领南京前后强行推行剃发令，以暴力手段压服汉人，扬州之屠与剃发令互为表里，都是清初民族压迫政策的组成部分。屠城之后，南京朝廷确实迅速瓦解，但江南民间的反抗也因之愈烈，嘉定、江阴等地军民以死相争，清军不得不付出更大代价平定江南，足见恐怖政策并不能真正压服人心。关于死亡人数，王秀楚所记「八十万余」历代颇有争议：以扬州城池规模与常居人口计，此数或近于夸大；惟屠城期间城中避难者甚众，确数已不可考。史学界主流认为，王秀楚亲历其事，其书为记载此事最详尽的文献，史料价值不容否认；屠城造成的人口损失虽难精确统计，但规模之大、惨酷之极，则无异议。扬州十日与嘉定三屠等事件一起，成为清代民族矛盾的重要根源，也为此后二百余年的反清运动埋下伏笔。",
