          "其时颙琰正在热河行宫行秋狝之礼，闻警急返。变起之夕，皇次子绵宁（后改旻宁，即道光帝）在养心殿持鸟枪连毙二贼，镇定指挥；礼亲王昭梿、成亲王永瑆等率众登城拒守，增援官兵陆续入宫合剿。当日教徒或死或擒，林清旋在京郊黄村被诱获，凌迟处死；李文成在河南滑县举事，据城自守，城破自焚而死。堂堂宫禁，竟被数十名教徒攻入，实为二千年帝制史上未有之奇变。",
          "颙琰回銮之后，颁下有清一代罕见的罪己诏，自述「笔随泪洒」，痛言此变为「汉唐宋明未有之事」，实大清之奇祸，并切责群臣因循废务、守土无状。诏下，整肃门禁，裁抑太监，失察官员分别治罪。其实祸机早伏：嘉庆八年（1803）闰二月，内务府厨役陈德已于神武门持刀行刺御驾，赖定亲王绵恩等拼死搏斗方擒。陈德自陈生计无着而行刺，终以父子凌迟结案。两次惊变，相去不过十年，腹心之地的空虚，已无可掩饰。"
