          "其时国势之衰，已不在一人之勤惰。吏治上，捐纳大开，胥吏把持钱粮词讼，州县官多成签押之傀儡；财政上，白莲教一役耗银二亿两，河工、赈灾岁费数百万，户部库银自乾隆晚年的七八千万两，降至嘉庆末年不足三千万两；社会上，人口逼近三亿，流民、棚民遍于川楚陕山区，秘密宗教以此为温床；对外，英国商船游弋闽粤洋面，鸦片输入由嘉庆初年每年三四千箱，增至道光初年逾万箱，白银外流之势已成。颙琰所行，皆传统勤政恤民之旧方，于结构之变，未见一策。",
