    interpretation: "颙琰之世，是清代由盛转衰的枢纽。乾隆朝「十全武功」、南巡与万寿的靡费，早已掏空国库；和珅二十年专权，将吏治的整体性腐败推向顶点：捐纳使卖官鬻爵半为常制，州县行政把持于胥吏之手，将弁兵丁冒功吃饷视为当然。颙琰以雷霆手段诛和珅，却只除其人、未除其制——罢贡献、行节俭、求直言，皆不出传统勤政恤民的范围；对财政、人口、土地、军制的结构性危机，并无因应之策。白莲教之乱耗银二亿两，几尽康雍乾百年之积蓄；天理教攻入禁城，更暴露朝廷腹心已朽。同一时期，工业革命后的英国正以鸦片叩关，清廷仍以天朝上国自处。嘉庆一朝的困境，是旧体制盛极而衰、危机总暴露的困境：勤政之主与朽坏之局相遇，个人的努力，反衬出时代的无力。",
