        heading: "督抚新政，权倾朝野",
        paragraphs: [
          "光绪二十七年（1901）李鸿章病逝，袁世凯署理直隶总督兼北洋大臣，次年实授。庚子善后中，他主持接收天津、恢复保定秩序，并以天津为试验场创办巡警、警务学堂与工艺局。财政上，他整顿银元、铜元与厘税，支持商务总会、实习工厂和铁路电报扩展，使直隶成为新政样板。军事上，他以小站旧部为基干，陆续编成北洋常备军，至光绪三十一年（1905）形成北洋六镇，兵力约七万人。",
          "与此同时，他把人事管道伸向全国。练兵处成立后，袁世凯任会办大臣，与铁良等共理军政；保定军官学堂、速成学堂、陆军小学次第设立，不少归国留学生经北洋体系考核任用。旧式武科与绿营裁汰、新军军制推广，皆与这一教育体系相配合。表面看，这是国家军事近代化；实际运作中，军权、饷权与袁氏门生网络紧密结合，清廷越来越难把北洋军队调离其创始者。",
          "光绪三十三年（1907），清廷调袁世凯为军机大臣兼外务部尚书，表面升迁，实则解除其直隶、北洋实权。光绪、慈禧死后，摄政王载沣于宣统元年（1909）以足疾令其回河南彰德养病。段祺瑞、冯国璋等旧部仍与他保持联络，袁世凯也在洹上村通过旧僚、亲信与电报消息观察朝局。朝廷虽罢其官，却不能收其势。这一矛盾，在武昌起义后迅速暴露。"
        ]
