    interpretation: "袁世凯的崛起是近代军政转型的产物。八旗绿营失效后，清廷把救亡希望押在新式陆军，却没有建立独立于个人与督抚网络的文官控制。袁世凯以小站为基地，把军制、学堂、财权与门生故吏合成效忠于己的北洋体系；朝廷越是依赖其武力，越须授以直隶总督、北洋大臣与内阁总理大臣等最高权力。辛亥之际，他既是清军统帅，又是南方可接受的强人，逼宫与议和互为筹码，使其实际接管民国。洪宪失败则说明，他看见强权效率，却低估共和观念、地方自治和民族危机下形成的新政治伦理；护国战争与北洋内部分裂，使他无法依靠旧班底重建帝制。他身后的北洋集团、南北对立与军阀割据，成为民初政治难以绕开的遗产。",
