      {
        heading: "洋务先驱与晚年",
        paragraphs: [
          "平乱之后，曾国藩倡自强之策，开洋务之端。同治四年（1865），他与李鸿章在上海创设江南制造总局，购西洋机器，造枪炮、修轮船，又设翻译馆译西书，为清末第一所大型近代军工企业；继而奏派容闳赴美国采购机器百数十部，扩充总局规模。同治十年（1871），他与李鸿章联名上奏，奏派幼童留美，议定每年选送三十名，四年共一百二十名，分批赴美学习军政、船政、制造，造就詹天佑等近代人才。湘淮将领由此次第倡办局厂，开洋务运动三十年之局。",
          "同治七年（1868），曾国藩调任直隶总督。任内整饬吏治，清理积案数万件。同治九年（1870）六月，天津教案爆发：民众因疑教堂迷拐幼孩，焚毁望海楼教堂，殴毙法国领事丰大业等二十人。曾国藩奉旨查办，处死为首十六人，军流徒二十五人，赔款四十九万七千余两，并将天津知府张光藻、知县刘杰革职戍边。法使罗淑亚步步紧逼，曾国藩以「外惭清议，内疚神明」自责，谤议四起，京师湖南会馆甚至将其牌匾砸毁。他遂以病坚请回任两江，黯然离直。",
          "同治十一年二月初四日（1872年3月12日），曾国藩卒于南京两江总督任上，年六十二。临逝前一日，犹与李鸿章商议留美幼童之事。朝廷追赠太傅，谥文正，入祀昭忠祠、贤良祠，各省建祠。有《曾国藩家书》《曾文正公全集》传世，流被极广；世传《冰鉴》一书则系后人托名，非其所作。曾国藩为晚清中兴名臣之首，亦是中国近代化开端的关键人物：他以一书生起于田间，终奠定湘淮军系与洋务自强之基，其功过是非，至今仍为史家聚讼之资。"
        ]
      }
