    interpretation: "《清史稿》论曰：「国藩事功本于学问，善以礼运。公诚之心，尤足格众。其治军行政，务求蹈实。」曾国藩一生，以理学起家，以军功立业，以洋务开新，恰是中国由传统向近代转折的缩影。他平定太平天国，保住了清王朝，却也亲手拆毁了清代兵制的旧基：湘军「兵为将有」的募勇制度，使督抚专政、军权下移，为日后北洋军阀割据伏下远因。他裁湘留淮，李鸿章继之而起，淮军又衍为北洋，晚清政局始终未脱其局。天津教案一役，他以内忧外患交逼之身，屈意求全，身被「汉奸」之谤，正见弱国无外交的困境。曾国藩之于近代中国，既是旧秩序的守护者，也是新文明的开门人——这种矛盾性本身，就是那个时代最真实的写照。",
