          "是年八月（1898年9月）政变骤作，六君子死难，陈宝箴父子革职永不叙用。张之洞以《劝学篇》预存持平之论，得孝钦皇后赏识，竟无恙。光绪二十六年（1900）义和团事起，两宫对外宣战，张之洞与两江总督刘坤一、闽浙总督许应骙等与各国领事订《东南互保约款》，东南半壁得免兵燹。同年七月（1900年8月），唐才常谋以自立军起事于汉口，张之洞先期破获，诛唐才常等二十余人，鄂局乃定。",
          "光绪二十七年（1901）两宫西狩之后，张之洞与刘坤一联衔上「江楚会奏三疏」，论兴学、变科举、练兵、恤商、奖实业，语皆切中时弊，为清末新政之蓝本。光绪二十九年（1903）入觐，奉命与张百熙、荣庆同订学堂章程，光绪三十年十一月（1904年1月）颁行，世称「癸卯学制」，近代学校制度于焉奠基。光绪三十一年（1905），与袁世凯、赵尔巽、周馥、岑春煊会奏立停科举，自隋以来千三百年之选举，至是尽废。"
