          "是年八月二十一日（1909年10月4日），张之洞病卒于北京，年七十二。赠太保，谥「文襄」，入祀贤良祠。丧归，家无余财，惟图书数万卷。《清史稿》论其「莅官所至，必有兴作，务宏大，不问费多寡」，而「任疆寄数十年，及卒，家不增一亩」。其一生兴作之费，动辄数百万两，库款、民捐、商股皆取之，鄂人颂其功，亦苦其需索。",
