    interpretation: "张之洞以清流入洋务，以儒臣任封疆，一生行迹恰是晚清「变与不变」之缩影。「中体西用」之论，在守旧与维新之间开出一条可操作之路：器物可变、制度缓变、纲常不动。此论使其在戊戌、庚子间剧烈摇荡中全身而退，亦使湖北得工业、军队、学堂之实。然铁厂亏耗、新政需财，终加派于民，湖广赋税甲于天下；其所练新军、所设学堂，多为辛亥革命之中坚，武昌首义即发于其工程第八营。赵尔巽《清史稿》论其「务宏大，不问费多寡」，正道出其功与弊：开风气之先者，亦伏后来之患。",
