    summary: "总理各国事务衙门，简称总理衙门，又称总署、译署，是清廷于咸丰十年十二月初十日（1861年1月20日）批准设立的中枢外交机构，由恭亲王奕䜣主持。其职初办通商、关税与对外交涉，后扩展至海关、同文馆、电报、铁路、矿务、机器制造、派遣驻外使节与留学生等洋务诸事，权比六部，时称「洋务内阁」。光绪二十七年（1901），据《辛丑条约》第十二款改为外务部，班列六部之首。总理衙门存在四十年，是中国从理藩旧制走向近代邦交体制的制度枢纽。",
    background: "咸丰十年（1860）八月，英法联军攻陷通州，咸丰帝以「北狩」为名走避热河避暑山庄，留恭亲王奕䜣为钦差便宜行事全权大臣，与大学士桂良、户部左侍郎文祥留京议和。九月，奕䜣先与英国全权大臣额尔金签订《中英北京条约》，继与法国全权大臣葛罗签订《中法北京条约》，并互换《天津条约》批准书。公使驻京、长江通商、内地游历等条款次第落实，交涉事务骤增。战前清廷并无专管外交的常设机构：藩属朝贡归礼部与理藩院，五口通商以来对外交涉例由两广总督兼「五口通商大臣」经办，遇重大争端则派钦差一事一办。咸丰帝甚至宁可全免洋货关税，也盼望各国公使「不入京」。联军入京证明，这一套以「羁縻」「抚夷」为底色的旧办法已彻底失效，留京议和的奕䜣、桂良、文祥深感事权不一之弊，遂起创设专署之念。",
