          "同治十年（1871），曾国藩、李鸿章联名上奏，援容闳所拟章程，请选派幼童赴泰西学习军政、船政、制造诸学。同治十一年（1872）七月，首批留美幼童三十名自上海启行，此后三年间续派三批，合计一百二十名，全部由总理衙门经理其事，陈兰彬、容闳分任正副监督。这是中国历史上第一次由政府组织的留洋教育，詹天佑、唐绍仪等即在其中，后来多成近代路矿、外交骨干。",
