          "甲午一败，朝野集矢于总理衙门，裁并之议渐起。戊戌变法期间，光绪帝下令广开言路，有臣工奏请裁撤冗署，总理衙门亦在讨论之列，因政变旋即发生，未及实行。庚子之役，八国联军陷京师，慈禧太后与光绪帝西逃西安，奕劻留京会同李鸿章与十一国议和。议和期间，列强坚持要求清廷成立专职外务机构，以杜绝昔日各衙门互相推诿、文书往复迁延之弊。",
          "光绪二十七年（1901）七月二十五日，《辛丑条约》签订，第十二款明定：总理各国事务衙门应即改为外务部，班列六部之首。清廷随即下谕裁撤总理衙门，新设外务部，以庆亲王奕劻为总理外务部事务大臣，那桐、徐寿朋为会办大臣。自咸丰十一年开局至此，总理衙门存在整整四十年而告终。其章京、书吏多为外务部留用，旧署档案亦移交新部。",
