        heading: "经略西北，平定陕甘",
        paragraphs: [
          "同治五年（1866）九月，左宗棠奉调陕甘总督。其时西北糜烂：陕甘回乱自同治元年起，回汉仇杀相循，董志原、金积堡、河州、西宁、肃州各路回军分据；西捻军张宗禹部复于同治六年（1867）由晋入陕，与回军呼应，关中震动。他受命后，立「先捻后回、先秦后陇」之策，先剿捻而后平回，亲督楚军入陕，至同治七年（1868）夏，西捻歼于直隶、山东之间，关中侧翼乃安。未几，他即移节西安，筹办甘肃军务，分道进兵，规画陇东、河西。",
          "同治八年（1869），左宗棠遣刘松山、刘锦棠老湘营进剿董志原，破回军十八大营，陇东告平。同治九年（1870）围攻金积堡，刘松山中炮阵亡，他以刘锦棠接统，长围久困，次年正月马化龙出降伏诛。其后兵分两路：一路趋河州，同治十一年（1872）太子寺战后受降马占鳌；一路趋西宁，同治十二年（1873）破白彦虎诸部。同年九月，克复河西走廊重镇肃州，马文禄伏诛，陕甘回乱悉平。自同治初年起绵延十余年、蹂躏陕甘数百里的兵燹至是告息，西征之路乃通。",
          "战事之外，左宗棠尤重戡乱后的经略。他奏准裁撤冗兵，招徕流亡，回民则分起安插，给以牛种，令各安生业；又督办屯田，开浚水利，广种桑麻，甘肃残破之地渐有起色。为筹西征军火，他于同治十一年（1872）在兰州设甘肃制造局，仿造洋枪洋炮；设兰州织呢局以裕利源。在甘期间，他清厘积案，整饬驿传，禁种罂粟，劝种棉花，西北吏治民风为之一变。凡此种种，不仅医治战创，更为西征奠定根本：粮台设于西安、汉口，军需转输于宁夏、包头，新疆建省之议亦在其胸中渐次成形。"
        ]
