    interpretation: "左宗棠一生，由落第举人而封侯拜相，其进身之阶异于科举正途，却正见清廷用人之变局。他所恃者非制义文章，而是舆地、兵农、漕盐、河工的经世之学——这恰是湘系集团崛起的底色。其历史地位要在两端：一则以武力收复新疆，于列强瓜分之秋保全一百六十余万平方公里疆土，并推新疆建省，改军府旧制为行省，开近代边疆治理之新局；二则创办福州船政局与船政学堂，以「师夷长技」自强，育海军人才数十载。其塞防之论与李鸿章海防之说相争，非纯是地域门户之见，实为财政竭蹶之下国防重心之辩。左宗棠以一身系西北安危者近二十年，晚岁抚闽督师，病殁于抗法前线，可谓尽瘁。后世论晚清支柱，曾、左、李、张并称，而以武功捍卫疆土论，左宗棠居功最伟。",
