    interpretation: "《古今图书集成》的命运，有两层深意。其一，是陈梦雷独创与身后名没的公案。梦雷两陷大狱，前因耿精忠之乱，后因诚亲王胤祉之败，其书经蒋廷锡重校删名，遂成钦定官书。古人修书，书以人传，亦以人废，诚亲王失势，则陈梦雷十年之功不得不没；世宗需要的是圣天子钦定之书，而非罪藩门客之稿。其二，是类书与丛书之别，关系文献保存方式的不同：《永乐大典》《古今图书集成》是把群书拆散、按类重编，读者得检查之便，却不见原书全貌；《四库全书》是整部收录、分类皮藏，存书之完，而检索为难。清廷以国家之力，康熙朝开其端，乾隆朝集其成，既笼络士林，又统一文献解释，此二书与《康熙字典》同为康乾文化政策之柱石。至于铜活字，虽为前无古人之举，然铸字工繁、排印费巨，印成之后，铜字或云销毁改铸他器，活字之术终未能如雕版般普及，于印刷史上，既是高峰，亦是绝响。",
