    interpretation: "《海国图志》之价值，首在由地理学入手而归结于军事改革的思想路径。魏源深悟制夷必先知夷，知夷则自舆地始——知其国在何处、其政何似、其长技何在，而后可以言战守。故其书先世界后中国，先地理后兵略，由「知」入手，以「行」为归。其「师夷长技以制夷」一语，含内在张力：目的在制夷，手段在师夷；所学限于器物——战舰、火器、养兵练兵之法——于西洋政教虽介绍赞赏，未尝欲行之中土，此即后来洋务派「中体西用」之先声。其内河防守之策固囿于当日力量对比，然设厂造船、译书练兵之议，实开三十年洋务实践之先河。中日接受史之悬异，尤为思想史上一大关目：日本在幕末危机中读之，急其所急，遂化为维新动力；中国在战败苟安之后读之，漠然置之，直至更大创痛继至。一书两命，可见一国之兴衰，固不系于一书之显晦，而系于其士大夫面对危机之诚意与魄力。",
