    interpretation: "《明儒学案》的深层意义，在于回答了「一代之思想如何被书写」的问题。在黄宗羲之前，正史《儒林传》以人系传、以经术仕进为重，朱熹《伊洛渊源录》虽述师承，仅录一派；黄宗羲则以「宗旨」为核心，以学派为纲、地域为脉，把二百余年、二百余家学术，整理为可考的谱系，创立真正之断代学术史体裁。其「一本万殊」之观尤为可贵：承认学术分歧之正当，以为道体无尽，不可以一家垄断真理，在尊朱辟王已成定局的清初，此尤为难能。书中对泰州学派的严厉批评与对东林、蕺山之推重，既见学术公心，亦含遗民身世之痛——他试图辨明：明亡之责不在心学本身，而在末流之失。全书保存之明代文献，多为后世亡佚之书，其甄别之精、评断之确，使它至今仍是研究明代理学不可替代的渊薮；后世《宋元学案》《清儒学案》递相祖述，学案体遂为中国学术史之典范体裁。",
