          "书成之初，仅以抄本流传，江南士人争相传写，声名渐著。版本回数，向有五十卷、五十五回、五十六回诸说，学者各有所据。传世刻本之最著者，为嘉庆八年（1803）卧闲草堂五十六回本，卷首有闲斋老人序。此本末四回叙事与前文风格不类，或出后人续补；亦有学者以为原作所有，争议至今未决。此后同治、光绪间翻刻本、评点本层出，如齐评本、天目山樵评本，皆自卧本系统衍出。",
