          "继而严氏兄弟：严监生临终伸着两根指头，只因灯盏里点了两茎灯草，迟迟不肯咽气，写尽悭吝之态；其兄严贡生则横行乡里，强圈邻人猪只，讹诈船家，以云片糕冒充毒药赖船资。马二先生游西湖，满目所接唯八股选文，对湖光山色了无会心。匡超人本一纯朴农家子弟，得马二先生资助教诲，后在杭州结识景兰江、赵雪斋一班斗方名士，代笔下场，步步堕落，终成忘恩负义之徒，最为全书堕落之典型。",
          "书中正面人物，当推杜少卿、沈琼枝辈。杜少卿散尽家财，携妻游清凉山，力辞朝廷征辟，其狂狷自适，显有作者自况性质。沈琼枝不甘为盐商宋为富之妾，逃至南京，卖诗文、做女红自立，刚烈可风。又有迟衡山、虞育德、庄绍光诸人，于南京兴建泰伯祠，行古礼、祭先贤，寄寓作者复兴礼乐之理想。而礼乐之梦终归虚幻，全书遂以市井四奇人收束：写字的季遐年、卖火纸筒的王太、开茶馆的盖宽、做裁缝的荆元，各怀绝技，寄文脉于平民。"
