    interpretation: "《儒林外史》之深层，在于写制度与人心之关系。八股取士本为抡才之制，行之既久，士子唯知揣摩墨卷，以功名为唯一价值，于是周进之屈辱、范进之癫狂、匡超人之堕落，皆非一人之过，而是制度性扭曲。吴敬梓自身由富贵而贫贱，既在制度之内，又得冷眼观之，故其讽刺不带戾气，而含悲悯。书中寄理想于杜少卿之狂狷、沈琼枝之刚烈、泰伯祠之礼乐，终归于市井奇人，可见作者于士林已近绝望，转认文化之根在民间。此书之影响不仅在文学，更为近代批判科举、反思士人传统之先声。",
