    interpretation: "绿营之制，其精义在防，不在战。将皆升转流官、兵皆土著世业，将不知兵、兵不知将，与宋代更戍法同一机杼；提督从一品而受节制于督抚，以文制武，兵权散于各省。如此则朝廷无拥兵之患，而军队亦无敢战之气。此为清初深谋，亦为后世积弊。国家养兵六十万，岁费不赀，而兵不能战。嘉庆元年（1796）川楚白莲教之役，绿营望风而溃，乃借乡勇以平乱；道光、咸丰间，鸦片战争、太平天国，绿营一败涂地，曾国藩、李鸿章乃以募勇别树一帜。湘淮军兴，兵为将有，将各募兵，统兵之权归于疆臣，清代二百年防兵之制，至此尽坏。其后防军、新军相代，而兵权下移之势，终成清末民初藩镇割据之局。故论清代兵制之变，绿营之废，实为中央集权向地方分权转折之枢纽。",
