    interpretation: "和珅之起落，是皇权畸形膨胀的产物。其进身不由科举正途，亦无军功，全恃乾隆帝一人恩眷，二十余年由侍卫至大学士，权兼将相，清代无第二人。乾隆晚年倦勤，需一近侍能臣办差承旨；内务府与户部分立，皇帝私库不受部臣稽核，和珅以议罪银、税关、盐课诸法为之罗致银两，既是聚敛之臣，亦是制度性需要的执行者。其权势之盛与败亡之速，皆系于此：恩眷在则权倾朝野，太上皇一崩则十六日之间家破身灭。和珅案折射乾隆盛世表象下的吏治危机：督抚以银抵罪，政以贿成，士子趋附，贤者蔽而不伸。嘉庆帝诛和珅，既除权臣，亦收内帑、立君威，然积重难返，清代国势自此由盛转衰，非一杀一抄所能挽回。",
