        heading: "阅微志怪 身后是非",
        paragraphs: [
          "《四库全书》告成后，纪昀于政务之暇，追录旧闻，陆续成《滦阳消夏录》（1789）、《如是我闻》（1791）、《槐西杂志》（1792）、《姑妄听之》（1793）、《滦阳续录》（1798）五集，门人盛时彦合刊为《阅微草堂笔记》二十四卷，凡一千二百余则。其书托狐鬼神怪以抒怀，写世情，寓劝惩，尚质黜华，不事描摹，与蒲松龄《聊斋志异》之曲尽人情、工于刻画异趣，别开一生面。记中多载乌鲁木齐见闻、京师人物、科场逸事，于乾嘉社会风俗、学术掌故皆有资焉。",
          "嘉庆元年（1796），纪昀转兵部尚书；嘉庆八年（1803），授协办大学士；嘉庆十年（1805）加太子太保。是年二月卒，年八十二岁，仁宗谕祭葬，谥曰文达。《清史稿》本传载其「胸襟夷旷，好为稗官小说，著阅微草堂笔记五种，盛行于时」。纪昀历仕两朝，官至卿贰，然其所以名垂青史者，不在台阁之高，而在总纂四库、手定提要与阅微之书。三者皆足以传世，亦足以见其人。",
          "民间多传纪昀与和珅斗智，今小说影视推波助澜，几于家喻户晓。然按之史实，和珅生于乾隆十五年（1750），少纪昀二十六岁，其用事在乾隆四十年代以后，其时纪昀方埋头四库馆中，日以审阅著书为务，二人虽同朝，地位悬殊，斗智轶事多为后世附会，未可据为信史。然纪昀博闻强记、敏捷诙谐，应对机锋之状，见于此间笔记野史者甚多，亦非全出虚构。要在辨其真伪，分际自明：纪昀之真面目，乃一淹贯群书、总持一代文献之学者，非弄臣也。"
        ]
