    interpretation: "纪昀一生，恰与清代文治鼎盛相终始。其大端有四：其一，《四库全书》之修，保存古籍三万六千余册，厥功至伟，而寓禁于征、缴毁禁书三千余种，实为思想统制，功过两端，同出一源，此乾隆朝文治之本质，纪昀身在其间，既受其成，亦与有其责。其二，《四库全书总目提要》二百卷，部有序、类有引，辨章学术、考镜源流，上承《七略》《汉志》之绪，下开近代书目之规，为古典目录学不可逾越之巅峰，至今为治古籍者所必资。其三，《阅微草堂笔记》尚质黜华，不事描摹，反映乾嘉朴学风气下之小说观，与《聊斋志异》之文采烂漫分道扬镳，各有千秋。其四，身后民间传说与和珅斗智之类，多为附会，反映世俗对文人机趣之想象，当以史实辨其分际：纪昀乃学者型官僚，非俳优弄臣。",
