    interpretation: "纳兰性德一生的意义，须从三重反差理解。其一，身份与性情的反差：身为大学士长子、御前侍卫，处烈火烹油之局，其词却凄恻清怨，「当时只道是寻常」式的日常书写，反使悼亡词获得超越时代的感染力——文学成就并不取决于阅历之顺逆，而系于性情之真。其二，满与汉的反差：王国维「以自然之眼观物，以自然之舌言情，未染汉人风气」之论，须辩证看待；性德实深染汉文化，师徐乾学、刻经解、交汉士，其「自然」恰恰来自对格律技巧与理学腔调的挣脱，而非文化的空白。其三，政治与学术的反差：《通志堂经解》卷帙逾千，实际辑佚以徐乾学门下之力为多，明珠家族出资刊刻，客观上配合了清廷崇儒右文、收揽士林的政策；性德个人在其中起到纽带作用。他三十一岁早逝，使清初词坛失却一位领袖，也使满汉文化交融少了一个标志性中介。《清史稿》「缠绵清婉，一代之冠」与王国维「北宋以来一人而已」之评，遂成定论。",
