    interpretation: "魏源一生的学术轨迹，呈显明的层累递进之结构。《皇朝经世文编》整理论治以内政，回答「如何治理国家」；《圣武记》追述开国之武功，回答「何以由盛转衰」；《海国图志》则跨出传统天下观，直面泰西诸国，回答「如何御侮图强」。三部书由内政而兵事，由兵事而洋务，正是一部完整的经世实学展开史。其思想核心，是今文经学的变易观与经世派的事功精神相结合：不囿于祖宗成法，不讳言敌国之长。「师夷长技以制夷」七字，承林则徐之实践而光大之，不仅为日后洋务运动「求强求富」辟出器物一途，其「悉夷情」「译西书」之议，更为近代思想启蒙埋下伏笔。魏源生前未见其说大行，然《海国图志》东传日本，翻刻数版，于明治维新人士多有影响，此亦思想史上一段佳话。",
