    interpretation: "预备立宪之失败，非在立宪本身，而在清廷以立宪为保权之术。载泽密奏所陈三利——皇位永固、外患渐轻、内乱可弭，句句为君主计，无一语为民权计；《钦定宪法大纲》以日本明治宪法为蓝本而集权更甚，君上大权十四条几无边界，九年预备期又漫长得足以消磨人心。反观日本明治维新，先废藩置县、设立民选议会，天皇虽尊而权受宪法限制，故能上下同心。清廷反之，既欲收立宪之名，又不愿分皇权之实，丙午官制改革以满汉平分保亲贵之利，皇族内阁更将十三阁员之九席归于满人、七席归于皇族，等于明告天下：立宪只为爱新觉罗一家一姓而设。谘议局、资政院本为清廷所造的合法议政平台，却恰恰成为立宪派动员三十余万人联名请愿的阵地，最终又转化为辛亥独立的中坚。政治改革之要，在于让被统治者相信体制可自我更新；一旦信用破产，迟来之《十九信条》再作大幅让步，亦无人采信。此即预备立宪未成而清朝先亡的制度史教训。",
