          "奉天会战，为当时世界最大之陆战。光绪三十一年（1905）二月下旬至三月上旬，日俄两军决战于奉天以南。日方大山岩部约三十一万人，俄方库罗帕特金、利涅维奇两部约三十六万人，合计七十余万众，战线绵延百余里。炮火连天，昼夜不息。俄军再败，北退四平街，损兵约六万；日军亦伤亡约七万，粮弹俱尽，无力追击。此役之后，陆战实际上趋于停顿，胜负已分而双方皆疲。",
          "海上决战，更定全局。俄国调波罗的海舰队组成第二太平洋舰队，由罗日杰斯特文斯基中将率领，自光绪三十年（1904）十月启程，绕行大半个地球，航程一万八千海里，劳师远征。光绪三十一年四月二十四日（1905 年 5 月 27 日），俄舰驶入对马海峡。东乡平八郎率联合舰队迎击，旗舰三笠号升 Z 旗，一战而全歼之：俄舰被击沉十九艘、被俘五艘，罗日杰斯特文斯基被俘，俄国海军精锐尽丧。同一时期，俄国国内流血星期日事件爆发，沙皇军队枪杀请愿民众，革命运动席卷全国，俄国自此无力再战。"
