          "俄国国内革命既起，前线又败，沙皇政府急于求和。美国总统西奥多·罗斯福出面斡旋，日俄全权代表会于美国新罕布什尔州朴茨茅斯。光绪三十一年八月七日（1905 年 9 月 5 日），两国订立《朴茨茅斯和约》：俄国承认朝鲜为日本势力范围，将库页岛南部割予日本，并将旅大租借地、长春以南铁路（即南满铁路）及俄国在南满之一切特权让渡于日本。清廷身为主权之国，竟未预其事，复被迫于光绪三十一年十一月二十六日（1905 年 12 月 22 日）与日本签订《中日会议东三省事宜条约》，承认朴约之各项安排，权益转手，悉出强权。",
          "战后日本经营南满，一如俄国之故技。光绪三十二年（1906），日本设关东都督府于旅顺，置关东州租借地；同年十一月，设立南满洲铁道株式会社，以参谋次长后藤新平为总裁，总揽铁路、矿山、移民、警察之权；又驻护路军于铁路沿线，即后来关东军之雏形。满洲权益尽入日本之手，形成国中之国，九一八之祸根、十四年抗战之远因，即植于此。清廷为自救，于光绪三十二年（1906）改革东三省官制，光绪三十三年（1907）四月设东三省总督，首任徐世昌，改盛京、吉林、黑龙江三将军为行省，推行新政，以图挽回利权。",
          "日本以立宪小国击败专制大国，震动亚洲。朝野舆论纷言：俄国之败，非败于军备，实败于专制之弊；日本之胜，非胜于舰炮，实胜于立宪之制。光绪三十一年（1905）七月，清廷派载泽、戴鸿慈、徐世昌、端方、绍英五大臣出洋考察宪政，归而力陈立宪之利，遂有光绪三十二年（1906）预备立宪之诏。印度、越南、波斯等地民族运动，亦受此战鼓舞而益振。一场发生在中国领土上之战争，竟成中国政制改革之催化剂，亦为亚洲觉醒之号角。"
